.header-example__glass {
  opacity: 0;
  transition: opacity 300ms ease;
}

.header-example[data-scrolled] .header-example__glass {
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .header-example__glass {
    transition: none;
  }
}

import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  connect() {
    this.scroll()
  }

  scroll() {
    this.element.toggleAttribute("data-scrolled", window.scrollY > 8)
  }
}

.mobile-example {
  --dock-gap: max(1rem, env(safe-area-inset-right, 0px));
  --dock-bottom: max(0.75rem, env(safe-area-inset-bottom, 0px));
  --dock-size: 4rem;
}

.mobile-example__main {
  padding-block-end: calc(var(--dock-bottom) + var(--dock-size) + 2rem);
}

.mobile-example__tabs {
  position: fixed;
  z-index: 20;
  inset-inline: max(1rem, env(safe-area-inset-left, 0px)) calc(var(--dock-gap) + var(--dock-size) + 0.75rem);
  bottom: var(--dock-bottom);
}

.mobile-example__tab {
  position: relative;
  display: flex;
  min-width: 0;
  min-height: 3.5rem;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  border-radius: 999px;
  color: var(--ink-2);
  font-size: 0.6875rem;
  font-weight: 600;
  text-decoration: none;
}

.mobile-example__tab[aria-current="page"] {
  color: var(--accent);
}

.mobile-example__indicator {
  position: absolute;
  z-index: -1;
  inset-block: 0.25rem;
  inset-inline-start: 0;
  border-radius: 999px;
  background: color-mix(in oklab, var(--ink) 7%, transparent);
  transition: translate 380ms var(--ease-sheet, ease), width 380ms var(--ease-sheet, ease);
}

.mobile-example__dock {
  position: fixed;
  z-index: 30;
  inset-inline-end: var(--dock-gap);
  bottom: var(--dock-bottom);
}

.mobile-example__trigger,
.mobile-example__action {
  display: grid;
  width: var(--dock-size);
  height: var(--dock-size);
  place-items: center;
  padding: 0;
  color: var(--accent);
  cursor: pointer;
}

.mobile-example__trigger {
  position: relative;
  z-index: 2;
}

.mobile-example__trigger svg {
  transition: rotate 300ms var(--ease-sheet, ease);
}

.mobile-example__trigger[aria-expanded="true"] svg {
  rotate: 135deg;
}

.mobile-example__actions {
  visibility: hidden;
  pointer-events: none;
}

.mobile-example__actions[data-open] {
  visibility: visible;
}

.mobile-example__scrim {
  position: fixed;
  inset: 0;
  border: 0;
  background: color-mix(in oklab, var(--ink) 18%, transparent);
  opacity: 0;
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
  transition: opacity 220ms ease;
}

.mobile-example__actions[data-open] .mobile-example__scrim {
  pointer-events: auto;
  opacity: 1;
}

.mobile-example__action {
  position: absolute;
  z-index: 1;
  inset: 0;
  width: 3.5rem;
  height: 3.5rem;
  margin: 0.25rem;
  color: var(--ink);
  opacity: 0;
  transform: scale(0.4);
  transition: transform 300ms ease, opacity 150ms ease;
}

.mobile-example__actions[data-open] .mobile-example__action {
  pointer-events: auto;
  opacity: 1;
  transform: translateY(calc(var(--action-index) * -4.5rem)) scale(1);
  transition: transform 420ms cubic-bezier(0.34, 1.45, 0.64, 1), opacity 160ms ease;
  transition-delay: calc((var(--action-index) - 1) * 40ms);
}

.mobile-example__action-label {
  position: absolute;
  inset-inline-end: calc(100% + 0.75rem);
  width: max-content;
  max-width: calc(100vw - 7rem);
  padding: 0.5rem 0.875rem;
  border-radius: 999px;
  background: var(--paper);
  box-shadow: var(--shadow);
  color: var(--ink);
  font-size: 0.875rem;
  font-weight: 600;
}

.mobile-example[data-keyboard] .mobile-example__tabs,
.mobile-example[data-keyboard] .mobile-example__dock {
  display: none;
}

@media (width >= 40rem) {
  .mobile-example__tabs {
    position: relative;
    inset: auto;
    width: max-content;
    margin-inline: auto;
    margin-block-end: 1.5rem;
  }

  .mobile-example__tab {
    min-width: 7rem;
    min-height: 2.75rem;
    flex-direction: row;
    gap: 0.5rem;
    font-size: 0.875rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mobile-example__indicator,
  .mobile-example__trigger svg,
  .mobile-example__scrim,
  .mobile-example__action,
  .mobile-example__actions[data-open] .mobile-example__action {
    transition: none;
  }
}

import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["link", "panel", "indicator", "status", "projects", "notes", "draft"]

  connect() {
    this.resizeObserver = new ResizeObserver(() => this.placeIndicator())
    this.linkTargets.forEach((link) => this.resizeObserver.observe(link))
    this.onViewportResize = () => this.keyboard()
    window.visualViewport?.addEventListener("resize", this.onViewportResize)
    this.placeIndicator()
  }

  disconnect() {
    this.resizeObserver.disconnect()
    window.visualViewport?.removeEventListener("resize", this.onViewportResize)
  }

  select(event) {
    event.preventDefault()
    this.show(event.currentTarget.hash.slice(1))
  }

  home(event) {
    event.preventDefault()
    this.show("projects")
  }

  show(id) {
    for (const link of this.linkTargets) {
      if (link.hash === `#${id}`) link.setAttribute("aria-current", "page")
      else link.removeAttribute("aria-current")
    }
    for (const panel of this.panelTargets) panel.hidden = panel.id !== id
    this.placeIndicator()
  }

  placeIndicator() {
    const active = this.linkTargets.find((link) => link.getAttribute("aria-current") === "page")
    this.indicatorTarget.style.translate = `${active.offsetLeft}px 0`
    this.indicatorTarget.style.width = `${active.offsetWidth}px`
  }

  add({ params: { destination } }) {
    const draft = this.draftTarget.content.cloneNode(true)
    const title = destination === "projects" ? "Untitled project" : "A new thought"
    draft.querySelector("[data-draft-title]").textContent = title
    const list = destination === "projects" ? this.projectsTarget : this.notesTarget
    list.prepend(draft)
    this.show(destination)
    this.statusTarget.textContent = `${title} added. Your next idea starts here.`
  }

  keyboard() {
    const typing = document.activeElement?.matches("input, textarea, [contenteditable=true]")
    const inset = window.innerHeight - (window.visualViewport?.height ?? window.innerHeight)
    this.element.toggleAttribute("data-keyboard", typing && inset > 150)
  }
}

.search-example__trigger {
  cursor: pointer;
  transition: background-color 160ms, color 160ms;
}

.search-example__dialog {
  position: fixed;
  inset: 0;
  inline-size: 100%;
  max-inline-size: none;
  block-size: 100%;
  max-block-size: none;
  margin: 0;
  padding: 0;
  border: 0;
  overflow: hidden;
  background: transparent;
  color: var(--ink);
}

.search-example__dialog::backdrop {
  background: color-mix(in oklab, var(--paper) 45%, transparent);
  -webkit-backdrop-filter: blur(16px) saturate(140%);
  backdrop-filter: blur(16px) saturate(140%);
}

.search-example__stack {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  inline-size: min(42rem, calc(100% - 1.5rem));
  block-size: 100%;
  margin-inline: auto;
  padding-block: max(0.75rem, env(safe-area-inset-top)) max(0.75rem, env(safe-area-inset-bottom));
}

.search-example__results {
  --glass-fill: color-mix(in oklab, var(--paper) 88%, transparent);
}

.search-example__input::-webkit-search-cancel-button {
  /* stylelint-disable-next-line property-no-vendor-prefix -- The clear button has an accessible label. */
  -webkit-appearance: none;
}

.search-example__result {
  border: 0;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}

.search-example__result:is(:hover, :focus-visible) {
  background: color-mix(in oklab, var(--ink) 6%, transparent);
}

.search-example [hidden] {
  display: none;
}

@media (width >= 40rem) {
  .search-example__trigger {
    inline-size: 21rem;
  }

  .search-example__stack {
    padding-block-start: 12vh;
  }

  .search-example__results {
    max-block-size: 65dvh;
  }
}

@media (prefers-reduced-transparency: reduce) {
  .search-example__dialog::backdrop {
    background: var(--paper);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

import { Controller } from "@hotwired/stimulus"
import { registerDialog } from "helpers/dialog"
import { prefersReducedMotion } from "helpers/viewport"

export default class extends Controller {
  static targets = [
    "dialog",
    "trigger",
    "input",
    "bar",
    "results",
    "result",
    "group",
    "empty",
    "clear",
    "summary",
    "shortcut",
    "selectionTitle",
    "selectionDetail",
    "selectionStatus",
  ]

  connect() {
    this.animations = []
    this.onShortcut = (event) => {
      if (event.isComposing || !(event.metaKey || event.ctrlKey) || event.key.toLowerCase() !== "k")
        return
      if (document.querySelector("dialog[open]") && !this.dialogTarget.open) return
      event.preventDefault()
      this.open()
    }
    document.addEventListener("keydown", this.onShortcut)
    this.shortcutTarget.textContent = /Mac|iPhone|iPad/.test(navigator.platform) ? "⌘ K" : "Ctrl K"
  }

  disconnect() {
    document.removeEventListener("keydown", this.onShortcut)
    this.returnFocus = null
    this.reset()
  }

  open() {
    if (this.closing) return
    if (this.dialogTarget.open) return this.inputTarget.focus()
    this.returnFocus =
      document.activeElement === document.body ? this.triggerTarget : document.activeElement
    this.filter()
    this.dialogTarget.showModal()
    this.unregisterDialog = registerDialog(this.dialogTarget, { close: () => this.close() })
    this.inputTarget.focus({ preventScroll: true })
    this.animate()
  }

  close() {
    if (!this.dialogTarget.open || this.closing) return
    this.closing = true
    this.animate({ reverse: true })
    Promise.allSettled(this.animations.map((animation) => animation.finished)).then(() =>
      this.reset(),
    )
  }

  reset() {
    this.animations.forEach((animation) => animation.cancel())
    this.animations = []
    this.dialogTarget.close()
    this.unregisterDialog?.()
    this.unregisterDialog = null
    this.closing = false
  }

  closed() {
    this.reset()
    this.returnFocus?.focus({ preventScroll: true })
    this.returnFocus = null
  }

  dismiss(event) {
    if (event.target.hasAttribute("data-search-dismiss")) this.close()
  }

  clear() {
    this.inputTarget.value = ""
    this.filter()
    this.inputTarget.focus()
  }

  filter(event) {
    if (event?.isComposing) return
    const query = this.inputTarget.value.normalize("NFKC").trim().toLowerCase()
    const words = query.split(/\s+/).filter(Boolean)
    let count = 0
    for (const result of this.resultTargets) {
      result.hidden = !words.every((word) => result.dataset.search.includes(word))
      if (!result.hidden) count++
    }
    for (const group of this.groupTargets) {
      group.hidden = !group.querySelector("[data-blocks-search-target=result]:not([hidden])")
    }
    this.clearTarget.hidden = !this.inputTarget.value
    this.emptyTarget.hidden = count > 0
    this.summaryTarget.textContent = query
      ? `${count} ${count === 1 ? "result" : "results"} for “${this.inputTarget.value.trim()}”`
      : "Start with something recent"
  }

  navigate(event) {
    if (event.isComposing || event.keyCode === 229) return
    const results = this.resultTargets.filter((result) => !result.hidden)
    const items = [this.inputTarget, ...results]
    const index = items.indexOf(document.activeElement)
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault()
      const step = event.key === "ArrowDown" ? 1 : -1
      items[Math.min(Math.max(index + step, 0), items.length - 1)].focus()
    } else if (event.key === "Enter" && document.activeElement === this.inputTarget) {
      event.preventDefault()
      results[0]?.click()
    }
  }

  select(event) {
    this.showSelection(event.currentTarget.dataset)
    this.close()
  }

  explore(event) {
    this.showSelection(event.currentTarget.dataset)
  }

  showSelection({ title, detail }) {
    this.selectionTitleTarget.textContent = title
    this.selectionDetailTarget.textContent = detail
    this.selectionStatusTarget.textContent = `Opened ${title}.`
  }

  animate({ reverse = false } = {}) {
    this.animations.forEach((animation) => animation.cancel())
    this.animations = []
    if (prefersReducedMotion()) return
    const from = this.triggerTarget.getBoundingClientRect()
    const to = this.barTarget.getBoundingClientRect()
    const insetY = Math.max((to.height - from.height) / 2, 0)
    const shiftY = from.top + from.height / 2 - (to.top + to.height / 2)
    const timing = {
      duration: reverse ? 200 : 360,
      easing: "cubic-bezier(0.16, 1, 0.3, 1)",
      direction: reverse ? "reverse" : "normal",
      fill: "both",
    }
    this.animations = [
      this.barTarget.animate(
        [
          {
            clipPath: `inset(${insetY}px ${to.right - from.right}px ${insetY}px ${from.left - to.left}px round 999px)`,
            translate: `0 ${shiftY}px`,
          },
          { clipPath: "inset(-1rem round 999px)", translate: "0 0" },
        ],
        timing,
      ),
      this.resultsTarget.animate(
        [
          { opacity: 0, translate: "0 -0.5rem" },
          { opacity: 1, translate: "0 0" },
        ],
        timing,
      ),
    ]
  }
}
